/*
 * vert-ui — shared motion
 * ---------------------------------------------------------------------------
 * Keyframes used by the animated components (overlays, menus, popovers,
 * accordion, collapsible, toast, progress, skeleton).
 *
 * Imported by both CSS entries (`index.css` and `vert.css`) and shipped as the
 * `vert-motion` registry item, so installing a component alone still animates.
 * Every keyframe animates transform/opacity only; the accordion/collapsible
 * reveals additionally animate height via Radix's content-height variables.
 */

@keyframes vert-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes vert-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@keyframes vert-accordion-down {
  from {
    height: 0;
    opacity: 0;
  }
  to {
    height: var(--radix-accordion-content-height);
    opacity: 1;
  }
}
@keyframes vert-accordion-up {
  from {
    height: var(--radix-accordion-content-height);
    opacity: 1;
  }
  to {
    height: 0;
    opacity: 0;
  }
}
@keyframes vert-collapsible-down {
  from {
    height: 0;
    opacity: 0;
  }
  to {
    height: var(--radix-collapsible-content-height);
    opacity: 1;
  }
}
@keyframes vert-collapsible-up {
  from {
    height: var(--radix-collapsible-content-height);
    opacity: 1;
  }
  to {
    height: 0;
    opacity: 0;
  }
}
@keyframes vert-pop-in {
  from {
    opacity: 0;
    transform: translateY(-4px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes vert-pop-out {
  from {
    opacity: 1;
    transform: none;
  }
  to {
    opacity: 0;
    transform: translateY(-4px) scale(0.97);
  }
}
@keyframes vert-swipe-out {
  from {
    transform: translateX(var(--radix-toast-swipe-end-x));
    opacity: 1;
  }
  to {
    transform: translateX(calc(var(--radix-toast-swipe-end-x) + 100%));
    opacity: 0;
  }
}
@keyframes vert-toast-in {
  from {
    opacity: 0;
    transform: translateX(110%);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}
@keyframes vert-toast-out {
  from {
    opacity: 1;
    transform: translateX(0);
  }
  to {
    opacity: 0;
    transform: translateX(110%);
  }
}
@keyframes vert-progress-indeterminate {
  0% {
    transform: translateX(-100%);
  }
  50% {
    transform: translateX(50%);
  }
  100% {
    transform: translateX(250%);
  }
}
@keyframes shimmer {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(100%);
  }
}

/*
 * Reduced-motion contract — single source of truth.
 * Imported by both CSS entries, so the override applies everywhere without the
 * two entries drifting apart. Overlays/menus stay mounted through Radix
 * Presence; collapsing the duration to ~0 makes them resolve instantly.
 */
@media (prefers-reduced-motion: reduce) {
  *,
  ::before,
  ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
